        return str(params[key])

    def block_repl(match: re.Match) -> str:
        return VAR_RE.sub(var_repl, blocks[match.group(1)])

    rendered = BLOCK_RE.sub(block_repl, skeleton)
    rendered = VAR_RE.sub(var_repl, rendered)

    leftover = LEFTOVER_RE.search(rendered)
    if leftover:
        raise LeftoverMarkerError(
            f"leftover marker {leftover.group(0)!r} survived rendering of {name!r}"
